  'stuSess.refundSuccessStripeNote':
    '<p class="text-emerald-900 text-sm mb-2">Klausimų ar nesklandumų — rašykite į <a href="mailto:info@tutlio.lt" class="underline font-medium">info@tutlio.lt</a>.</p><p class="font-semibold text-emerald-900">Grąžinimas inicijuotas per Stripe.</p><p class="text-emerald-800 mt-1">Pinigai į kortelę paprastai grįžta per <strong>5–10 darbo dienų</strong> (banko laikai gali skirtis). Jei per įprastą laiką nesulauksite — rašykite į <a href="mailto:info@tutlio.lt" class="text-emerald-900 underline font-medium">info@tutlio.lt</a>.</p>',
