  'stuSess.refundSuccessManualOrg': '<p>Ši pamoka, matyt, buvo apmokėta ne per Tutlio Stripe (pvz., pavedimu ar kitaip). Automatinio grąžinimo čia nėra.</p><p class="mt-2">Kadangi mokotės per organizaciją, dėl grąžinimo kreipkitės į <strong>organizacijos administratorių</strong> (per savo korepetitorių arba organizacijos nurodytus kontaktus).</p>',
