  'landing.faq.whatIsQ': 'Kas yra Tutlio?',
  'landing.faq.whatIsA': 'Tutlio — tai korepetavimo valdymo platforma, padedanti privatiems korepetitoriams ir mokykloms valdyti tvarkaraštį, mokėjimus, komunikaciją su mokiniais ir pamokų istoriją vienoje vietoje.',
  'landing.faq.whoForQ': 'Kam skirtas Tutlio?',
  'landing.faq.whoForA': 'Tutlio sukurtas privatiems korepetitoriams, muzikos mokytojams, kalbų dėstytojams, matematikos repetitoriams, korepetavimo mokykloms ir švietimo centrams.',
  'landing.faq.waitlistQ': 'Kaip veikia mokinių laukimo eilė?',
  'landing.faq.waitlistA': 'Kai mokinys atšaukia pamoką, atlaisvinta vieta automatiškai pasiūloma laukimo eilėje esantiems mokiniams. Kas pirmas patvirtina — tas gauna vietą, todėl korepetitorius nepraranda pajamų.',
  'landing.faq.freeTrialQ': 'Ar yra nemokamas bandomasis laikotarpis?',
  'landing.faq.freeTrialA': 'Taip! Visos naujos paskyros automatiškai gauna 7 dienas nemokamai – jokio kodo nereikia. Per bandomąjį laikotarpį neapmokestinama, galite atšaukti bet kada.',
  'landing.faq.languagesQ': 'Kokiomis kalbomis veikia Tutlio?',
  "landing.faq.languagesA": "Tutlio veikia {count} kalbų: {languages}.",
  'landing.faqTitle': 'Dažnai užduodami klausimai',

  'landing.feature.digital-business-card': 'Skaitmeninė vizitinė kortelė',
  'landing.feature.digital-business-cardDesc': 'Viena profesionali nuoroda, kurioje mokiniai susipažįsta su jumis, mato aktualias kainas bei laisvus laikus ir iš karto pateikia pamokos užklausą.',
  'featuresIndex.newBadge': 'Naujiena',
  'feature.digital-business-card.pageTitle': 'Skaitmeninė vizitinė, kuri susidomėjimą paverčia pamokų užklausomis',
  'feature.digital-business-card.pageDesc': 'Suteikite būsimam mokiniui vieną profesionalią nuorodą su jūsų prisistatymu, pamokomis, kainomis, atsiliepimais ir gyvai atnaujinamais laisvais laikais. Mokinys iš karto pasirenka pamoką bei laiką, o jūs nebeprarandate užklausų ilgose žinučių grandinėse.',
  'feature.digital-business-card.detailsTitle': 'Viskas, ko būsimam mokiniui reikia apsispręsti',
  'feature.digital-business-card.oneLink': 'Viena nuoroda visai jūsų korepetitoriaus veiklai',
  'feature.digital-business-card.oneLinkDesc': 'Pakeiskite išmėtytus socialinius profilius, kainoraščius ir registracijos žinutes vienu puslapiu, kuriuo patogu dalytis visur.',
  'feature.digital-business-card.liveAvailability': 'Visada aktualūs laisvi laikai',
  'feature.digital-business-card.liveAvailabilityDesc': 'Laisvi laikai imami tiesiai iš jūsų Tutlio kalendoriaus, todėl klientai renkasi tik tuos laikus, kuriais iš tikrųjų norite dirbti.',
  'feature.digital-business-card.instantEnquiries': 'Pamokų užklausos, kol jūs mokote',
  'feature.digital-business-card.instantEnquiriesDesc': 'Tėvai ar mokinys pasirenka pamoką, formatą bei laiką ir palieka kontaktus. Išsami užklausa pasiekia jus be derinimo žinutėmis.',
  'feature.digital-business-card.professionalBrand': 'Profesionalus pirmasis įspūdis',
  'feature.digital-business-card.professionalBrandDesc': 'Parodykite savo nuotrauką, mokymo būdą, dalykus, kainas, patvirtintus atsiliepimus ir spalvas puslapyje, kuris puikiai veikia telefone.',
  'feature.digital-business-card.faq.whatShowsQ': 'Ką galiu rodyti savo skaitmeninėje vizitinėje?',
  'feature.digital-business-card.faq.whatShowsA': 'Galite pateikti prisistatymą, dalykus, pamokų formatus, viešas kainas, laisvus kalendoriaus laikus, vietą, kalbas, socialinių tinklų nuorodas ir patvirtintus mokinių atsiliepimus.',
  'feature.digital-business-card.faq.howBookingWorksQ': 'Ar klientas iš karto rezervuoja patvirtintą pamoką?',
  'feature.digital-business-card.faq.howBookingWorksA': 'Klientas pasirenka pamoką ir laisvą laiką, tada atsiunčia išsamią rezervacijos užklausą. Ją gaunate Tutlio ir galite patvirtinti naują mokinį prieš įtraukdami pamoką į tvarkaraštį.',
  'feature.digital-business-card.faq.whereShareQ': 'Kur geriausia dalytis vizitinės nuoroda?',
  'feature.digital-business-card.faq.whereShareA': 'Įkelkite ją į Instagram, TikTok, Facebook grupes, reklamas, el. pašto parašą, žinutes ar QR kodą. Viena nuoroda išlieka aktuali net pakeitus kainas ar kalendorių.',
  'feature.digital-business-card.demo.eyebrow': 'Interaktyvi kliento peržiūra',
  'feature.digital-business-card.demo.title': 'Išbandykite rezervacijos kelią',
  'feature.digital-business-card.demo.desc': 'Žemiau pasirinkite pamoką ir laiką. Tokį paprastą kelią naujas klientas matys atidaręs jūsų nuorodą.',
  'feature.digital-business-card.demo.profile': 'Matematikos korepetitorė · 9–12 kl.',
  'feature.digital-business-card.demo.available': 'Priima naujus mokinius',
  'feature.digital-business-card.demo.pickLesson': '1. Pasirinkite pamoką',
  'feature.digital-business-card.demo.individual': 'Individuali pamoka',
  'feature.digital-business-card.demo.individualDesc': '60 min. · asmeninis mokymosi planas',
  'feature.digital-business-card.demo.exam': 'VBE intensyvas',
  'feature.digital-business-card.demo.examDesc': '90 min. · kryptingas pasiruošimas',
  'feature.digital-business-card.demo.trial': 'Susipažinimo pokalbis',
  'feature.digital-business-card.demo.trialDesc': '20 min. · susipažinti ir aptarti tikslus',
  'feature.digital-business-card.demo.pickTime': '2. Pasirinkite laisvą laiką',
  'feature.digital-business-card.demo.tomorrow': 'Rytoj',
  'feature.digital-business-card.demo.thursday': 'Ketvirtadienį',
