  'orgTutorPolicy.title': 'Vidinės taisyklės mokytojams',
  'orgTutorPolicy.intro': 'Prieš pradėdami naudotis platforma, susipažinkite su organizacijos vidinėmis taisyklėmis.',
  'orgTutorPolicy.acceptBtn': 'Supratau',
  'orgTutorPolicy.viewBtn': 'Peržiūrėti vidines taisykles',
  'orgTutorPolicy.s1Title': '1. Bendrosios nuostatos',
  'orgTutorPolicy.s1Body': 'Šios taisyklės reglamentuoja jūsų, kaip mokytojo ar korepetitoriaus (toliau — Mokytojas), naudojimąsi „Tutlio“ platforma (toliau — Platforma). Naudotis Platforma jus pakvietė jūsų atstovaujama švietimo agentūra, mokykla ar korepetitorių centras (toliau — Organizacija). Platformą techniškai aptarnauja ir palaiko MB „Tutlio“. Naudodamiesi paskyra sutinkate su šiomis Taisyklėmis ir Privatumo politika.',
  'orgTutorPolicy.s2Title': '2. Paskyros valdymas ir tvarkaraščiai',
  'orgTutorPolicy.s2Intro': 'Platforma sukurta taip, kad Jums nereikėtų gaišti laiko derinant pamokų laikus su mokiniais.',
  'orgTutorPolicy.s2Link': 'Unikali nuoroda: Jums priskiriama asmeninė pamokų rezervacijos nuoroda (pagal Jūsų dėstomus dalykus), kuria mokiniai naudojasi užsakydami pamokas.',
  'orgTutorPolicy.s2Calendar': 'Kalendoriaus sinchronizacija: jūsų užimtumas tiesiogiai priklauso nuo dvipusės „Google Calendar“ integracijos. Esate atsakingi už tai, kad kalendoriuje nurodytas laisvas laikas būtų tikslus ir aktualus. Platforma neleis mokiniams rezervuoti laiko, kuris kalendoriuje pažymėtas kaip užimtas.',
  'orgTutorPolicy.s2Security': 'Paskyros saugumas: Paskyra yra asmeninė. Prisijungimo duomenis privalote saugoti ir neperduoti tretiesiems asmenims.',
  'orgTutorPolicy.s3Title': '3. Pamokų atšaukimai ir laukimo eilė',
  'orgTutorPolicy.s3Intro': 'Platforma padeda kuo geriau užpildyti jūsų tvarkaraštį ir išvengti „tuščių langų“:',
  'orgTutorPolicy.s3Auto': 'Jei mokinys atšaukia pamoką, Platforma automatiškai išsiunčia pranešimą (SMS/el. paštu) kitiems Jūsų laukimo eilėje esantiems mokiniams, siūlydama užimti atsilaisvinusį laiką. Jums jokių papildomų veiksmų atlikti nereikia.',
  'orgTutorPolicy.s3Rules': 'Pamokų atšaukimo taisykles (prieš kiek laiko galima atšaukti, kokios pasekmės) nustato Jūsų Organizacija.',
  'orgTutorPolicy.s4Title': '4. Finansai ir atsiskaitymai',
  'orgTutorPolicy.s4Intro': 'Jums nereikia rūpintis sąskaitų išrašymu ar pinigų reikalavimu iš tėvų:',
  'orgTutorPolicy.s4Advance': 'Visi mokinių (ar jų tėvų) apmokėjimai už Jūsų vedamas pamokas surenkami avansu per Platformą ir pervedami tiesiai Jūsų Organizacijai.',
  'orgTutorPolicy.s4Confirmed': 'Pamoką vedate tik tada, kai ji patvirtinta sistemoje — tai reiškia, kad už ją jau atsiskaityta.',
  'orgTutorPolicy.s4Contact': 'Dėl atlyginimo, išmokėjimų tvarkos ir kitų finansinių klausimų kreipkitės tiesiogiai į savo Organizacijos administratorių. MB „Tutlio“ nevykdo tiesioginių finansinių atsiskaitymų su Mokytojais.',
  'orgTutorPolicy.s5Title': '5. Mokinių duomenų apsauga (BDAR)',
  'orgTutorPolicy.s5Intro': 'Kaip Mokytojas, Jūs gaunate prieigą prie mokinių asmens duomenų, vidinių užrašų (pastabų) ir mokymosi medžiagos. Jūs įsipareigojate:',
  'orgTutorPolicy.s5Use': 'Naudoti šiuos duomenis išskirtinai tik pamokų organizavimui ir vedimui.',
  'orgTutorPolicy.s5NoCopy': 'Nekopijuoti, neeksportuoti ir neplatinti mokinių ar jų tėvų kontaktinės informacijos už Platformos ribų.',
  'orgTutorPolicy.s5Notes': 'Saugoti vidinius Organizacijos įrašus (pastabas apie mokinio progresą), kurie yra matomi tik Jums ir Organizacijos administracijai, bet ne mokiniams ar tėvams.',
  'orgTutorPolicy.s5Termination': 'Pasibaigus Jūsų darbo santykiams su Organizacija, Jūsų prieiga prie šių duomenų bus nedelsiant nutraukta.',
  'orgTutorPolicy.s6Title': '6. Techninis veikimas ir atsakomybės ribojimas',
  'orgTutorPolicy.s6Body': 'Draudžiama naudoti Platformą neteisėtiems tikslams, platinti kenkėjiškas nuorodas pamokų medžiagoje ar kitaip trikdyti sistemos darbą. MB „Tutlio“ užtikrina Platformos veikimą ir techninę priežiūrą, tačiau neprisiima atsakomybės už nesklandumus, kilusius dėl jūsų interneto ryšio, įrenginių gedimų ar neteisingų „Google Calendar“ nustatymų.',
  'orgTutorPolicy.s7Title': '7. Pagalba ir kontaktai',
  'orgTutorPolicy.s7Org': 'Jei susiduriate su klausimais dėl pamokų grafikų, atlyginimų, mokinių priskyrimo ar darbo organizavimo, kreipkitės į savo Organizacijos administratorių.',
  'orgTutorPolicy.s7Tech': 'Jei susiduriate su techninėmis Platformos klaidomis (neveikia kalendoriaus sinchronizacija ar negaunate pranešimų), praneškite Organizacijos administratoriui, kuris susisieks su „Tutlio“ techninio palaikymo komanda.',

