  'feature.cancellation.pageTitle': 'Atšaukimo taisyklės ir vėlyvo atšaukimo mokesčiai korepetitoriams',
  'feature.cancellation.pageDesc': 'Nustatykite aiškius atšaukimo terminus ir automatinius vėlyvo atšaukimo mokesčius. Kai mokiniai atšaukia, atsilaisvinę laikai iškart patenka į jūsų laukiančiųjų sąrašą.',
  'feature.cancellation.detailsTitle': 'Kaip veikia atšaukimo taisyklės',
  'feature.cancellation.deadlines': 'Atšaukimo terminai',
  'feature.cancellation.deadlinesDesc': 'Nurodykite, kiek iš anksto mokiniai turi atšaukti (pvz., 24 val. iki pamokos), kad išvengtų atšaukimo mokesčio.',
  'feature.cancellation.fees': 'Automatiniai vėlyvo atšaukimo mokesčiai',
  'feature.cancellation.feesDesc': 'Nustatykite procentinį mokestį (pvz., 50 % pamokos kainos), kuris automatiškai taikomas, kai mokinys atšaukia per vėlai.',
  'feature.cancellation.transparency': 'Aiškus bendravimas su mokiniais',
  'feature.cancellation.transparencyDesc': 'Mokiniai mato jūsų atšaukimo politiką iš karto rezervuodami. Jokių staigmenų – tik profesionalios, sąžiningos taisyklės.',
  'feature.cancellation.waitlistLink': 'Integracija su laukiančiųjų sąrašu',
  'feature.cancellation.waitlistLinkDesc': 'Atšaukti laikai iškart pasiūlomi laukiantiems mokiniams, todėl jūsų tvarkaraštis lieka užpildytas, o pajamos apsaugotos.',
  'feature.cancellation.faq.howSetQ': 'Kaip nustatyti atšaukimo taisykles?',
  'feature.cancellation.faq.howSetA': 'Eikite į pamokų nustatymus ir nurodykite atšaukimo terminą (valandos iki pamokos) bei vėlyvo atšaukimo mokesčio procentą. Sistema juos taiko automatiškai.',
  'feature.cancellation.faq.refundQ': 'Kas nutinka su atšaukimo mokesčiu?',
  'feature.cancellation.faq.refundA': 'Vėlyvo atšaukimo mokesčiai apskaičiuojami automatiškai ir pridedami prie mokinio balanso. Visus mokesčius galite stebėti finansų skydelyje.',
  'feature.cancellation.faq.studentSeeQ': 'Ar mokiniai mato atšaukimo politiką?',
  'feature.cancellation.faq.studentSeeA': 'Taip, jūsų atšaukimo sąlygos rodomos mokiniams rezervavimo metu, kad jie žinotų taisykles prieš patvirtindami.',
  'feature.comments.pageTitle': 'Pamokų pastabos, komentarai ir failų dalijimasis korepetitoriams',
  'feature.comments.pageDesc': 'Pridėkite pastabas, namų darbus ir failus prie atskirų pamokų. Sukurkite pilną pamokų istoriją, prieinamą mokiniams ir tėvams bet kada.',
  'feature.comments.detailsTitle': 'Kaip veikia pamokų pastabos',
  'feature.comments.lessonNotes': 'Pastabos kiekvienai pamokai',
  'feature.comments.lessonNotesDesc': 'Pridėkite privačias ar bendrinamas pastabas prie bet kurios pamokos – fiksuokite, kas išeita, mokinio pažangą ir kitus žingsnius.',
  'feature.comments.fileSharing': 'Failų priedai',
  'feature.comments.fileSharingDesc': 'Įkelkite užduočių lapus, namų darbų PDF ar mokymosi medžiagą ir pridėkite juos tiesiai prie pamokos, kad būtų lengva pasiekti.',
  'feature.comments.history': 'Pilna pamokų istorija',
  'feature.comments.historyDesc': 'Kiekviena pastaba ir failas susiejami su atitinkama pamoka, todėl lengva peržiūrėti visą mokinio mokymosi istoriją.',
  'feature.comments.parentAccess': 'Matomumas tėvams',
  'feature.comments.parentAccessDesc': 'Tėvai gali matyti bendrinamas pamokų pastabas ir failus savo portale, todėl yra informuoti apie vaiko pažangą.',
  'feature.comments.faq.whoSeesQ': 'Kas gali matyti pamokų pastabas?',
  'feature.comments.faq.whoSeesA': 'Jūs pasirenkate, ką bendrinti. Pastabos gali būti privačios (tik korepetitoriui) arba bendrinamos su mokiniu ir jo tėvais.',
  'feature.comments.faq.fileTypesQ': 'Kokius failų tipus galiu įkelti?',
  'feature.comments.faq.fileTypesA': 'Galite įkelti PDF, paveikslėlius ir įprastus dokumentų formatus. Failai saugomi saugiai ir pasiekiami iš bet kurio įrenginio.',
  'feature.comments.faq.storageQ': 'Ar yra saugyklos limitas?',
  'feature.comments.faq.storageA': 'Visi planai apima dosnią failų saugyklą. Nėra atskirų failų limitų – pridėkite tiek medžiagos, kiek reikia.',
