  'quiz.info.story.company.story': '„Iki Tutlio pamokų pakeitimai, komentarai ir korepetitorių valandos buvo išmėtyti žinutėse. Dabar visa komanda dirba pagal tą patį tvarkaraštį, o mėnesio pabaigoje nebereikia vaikytis trūkstamų duomenų.“',
