  'quiz.info.story.company.proof3': 'Pamokų kontrolė',
  'quiz.info.story.company.detail': '„Didžiausias skirtumas tas, kad patvirtinimai, kompensacinės pamokos ir atlygio taisyklės pritaikytos prie mūsų komandos darbo, o ne mes prie bendrinės sistemos.“',
