  'quiz.info.story.school.customerType': 'Mokyklos administracijos komanda',
  'quiz.info.story.school.story': '„Norėjome vienos vietos, kurioje komanda galėtų sekti šeimos kelią nuo priėmimo ir sutarties iki kiekvienos įmokos. Tutlio tai leidžia daryti be lygiagrečių skaičiuoklių.“',
