  'quiz.offer.testimonials.goTo': 'Rodyti {number} atsiliepimą',
  'quiz.offer.testimonial.solo.name3': 'Ieva',
  'quiz.offer.testimonial.solo.role3': 'Chemijos ir biologijos korepetitorė',
  'quiz.offer.testimonial.solo.copy3': '„Viešas puslapis ir rezervacija vienoje nuorodoje padėjo naujiems mokiniams apsispręsti greičiau, o man nebereikia kiekvienam atskirai siųsti tos pačios informacijos.“',
  'quiz.offer.testimonial.solo.name4': 'Lukas',
  'quiz.offer.testimonial.solo.role4': 'Fizikos korepetitorius',
  'quiz.offer.testimonial.solo.copy4': '„Kalendoriuje iš karto matau pamokas, pakeitimus ir mokėjimų būsenas. Kasdienė administracija tapo daug trumpesnė ir aiškesnė.“',
  'quiz.offer.testimonial.company.name1': 'PRO KLASĖ',
  'quiz.offer.testimonial.company.role1': 'Korepetitorių organizacijos komanda',
  'quiz.offer.testimonial.company.copy1': '„Pamokų pakeitimai, korepetitorių komentarai ir valandos anksčiau ateidavo atskiromis žinutėmis. Dabar administracijos komanda visą vaizdą mato viename tvarkaraštyje.“',
  'quiz.offer.testimonial.company.name2': 'Nepriklausomas korepetitorių centras',
  'quiz.offer.testimonial.company.role2': 'Savininkė · 8 korepetitoriai',
  'quiz.offer.testimonial.company.copy2': '„Penktadienio vakarais lygindavau kalendorių su korepetitorių žinutėmis ir tik tada ruošdavau atlygius. Su Tutlio didžioji dalis šio tikrinimo jau būna padaryta.“',
  'quiz.offer.testimonial.company.name3': 'Kalbų korepetitorių studija',
  'quiz.offer.testimonial.company.role3': 'Veiklos vadovė · 14 korepetitorių',
  'quiz.offer.testimonial.company.copy3': '„Perkėlus pamoką visa komanda iš karto mato tą patį pakeitimą. Turime mažiau papildomų žinučių, o tėvams galime atsakyti daug aiškiau.“',
  'quiz.offer.testimonial.company.name4': 'Egzaminų pasiruošimo akademija',
  'quiz.offer.testimonial.company.role4': 'Finansų koordinatorė · 22 korepetitoriai',
  'quiz.offer.testimonial.company.copy4': '„Korepetitorių atlygio taisyklės priklauso nuo pamokos tipo, todėl mėnesio pabaigoje daug ką tikrindavome rankomis. Tutlio šį procesą padarė gerokai ramesnį.“',
  'quiz.offer.testimonial.school.name1': 'VšĮ „Laisvi vaikai“',
  'quiz.offer.testimonial.school.role1': 'Mokyklos administracijos komanda',
  'quiz.offer.testimonial.school.copy1': '„Didžiausias palengvėjimas – sutarties, parašo ir mokėjimo būseną matome neklausinėdami kelių žmonių ir netikrindami atskirų failų.“',
  'quiz.offer.testimonial.school.name2': 'Nepriklausoma bendruomeninė mokykla',
  'quiz.offer.testimonial.school.role2': 'Priėmimo koordinatorė · 86 mokiniai',
  'quiz.offer.testimonial.school.copy2': '„Per mokinių priėmimą anksčiau formas, tėvų duomenis ir pasirašytas sutartis sekdavome atskiruose aplankuose. Dabar kiekvienos šeimos kelią matome vienoje vietoje.“',
  'quiz.offer.testimonial.school.name3': 'Popamokinio ugdymo centras',
  'quiz.offer.testimonial.school.role3': 'Administratorė · 120 mokinių',
  'quiz.offer.testimonial.school.copy3': '„Įmokų grafikai mokėjimų sekimą padarė daug ramesnį. Prieš susisiekdama su tėvais matau, kas artėja, ir nebereikia sąrašo rinkti rankomis.“',
  'quiz.offer.testimonial.school.name4': 'Meninio ugdymo mokykla',
  'quiz.offer.testimonial.school.role4': 'Finansų koordinatorė · 9 programos',
  'quiz.offer.testimonial.school.copy4': '„Buhalterijos eksportas dabar remiasi tais pačiais duomenimis kaip sutartys ir mokėjimai, todėl mėnesio pabaigoje tenka taisyti gerokai mažiau.“',
